    }
    sql << '),\n'
    sql << 'per_month AS (\n'
    sql << '  SELECT department, month, sum(cost) AS cost, count(*) AS people\n'
    sql << '  FROM lines\n'
    sql << '  GROUP BY department, month\n'
    sql << '),\n'
    sql << 'paired AS (\n'
    sql << '  SELECT n.department AS department,\n'
    sql << '         n.people AS people_now,\n'
