    sql << '  FROM per_month n\n'
    sql << '  JOIN per_month p\n'
    sql << '    ON p.department = n.department\n'
    sql << '   AND p.month = n.month - INTERVAL 12 MONTH\n'
    sql << ')\n'
    sql << 'SELECT department,\n'
    sql << '       people_now - people_last_year AS people_change,\n'
    sql << '       round(cost_now - cost_last_year, 2) AS cost_change,\n'
    sql << '       round((people_now - people_last_year) * (cost_last_year / people_last_year), 2) AS from_more_people,\n'
